    {
      "n": "#11·06",
      "text": "A soft graphite turtleneck sweater with dropped shoulders and ribbed cuffs, designed for comfort without sacrificing style. Its relaxed fit drapes gently over the frame, making movement effortless."
    },
    {
      "n": "#130·34",
      "text": "Wide-leg grey jeans cut straight through the thigh and tapering slightly at the ankle, offering both structure and ease. The muted wash pairs beautifully with your other pieces."
    },
    {
      "n": "#271·21",
      "text": "A bold red crossbody bag with a glossy crocodile texture and a sleek gold buckle clasp that catches the light subtly. It adds a touch of energy to your otherwise neutral look."
    },
    {
      "n": "#567·03",
      "text": "Dark brown suede ballet flats with a low profile and flexible sole, crafted for all-day wear. Their rounded toe and slip-on design make them ideal for yoga or strolling."
    },
    {
      "n": "#346·06",
      "text": "A khaki-toned bomber jacket with a high stand collar and structured shoulders that define the upper body. Made from smooth material, it offers warmth without bulk, and its cropped length keeps the silhouette clean."
    }
  ]
